const code=`Object.defineProperty(process.stdin,'isTTY',{value:true});Object.defineProperty(process.stdout,'isTTY',{value:true});Object.defineProperty(process.stdout,'columns',{value:120});Object.defineProperty(process.stdout,'rows',{value:42});process.stdin.setRawMode=()=>process.stdin;process.argv=['node',${JSON.stringify(entry)},'--cwd',${JSON.stringify(cwd)}];await import(${JSON.stringify(pathToFileURL(entry).href)});`;
const tui=spawn(process.execPath,['--input-type=module','-e',code],{cwd,env:process.env,windowsHide:true,stdio:['pipe','pipe','pipe']});let screen='',err='';tui.stdout.on('data',s=>screen+=s);tui.stderr.on('data',s=>err+=s);const deadline=Date.now()+20000;const wait=async test=>{while(Date.now()<deadline){if(test())return;await new Promise(r=>setTimeout(r,30));}throw new Error('Node TTY harness timeout '+err+screen.slice(-1500));};
try{await wait(()=>screen.includes('CCPT'));tui.stdin.write(`/undo-conflict ${resolved.id}\r`);await wait(()=>screen.includes('Undo this exact conflict resolution?'));tui.stdin.write('\x1b');await wait(()=>screen.includes('dialog dismissed'));tui.stdin.write('/exit\r');await new Promise((r,j)=>{const t=setTimeout(()=>j(new Error('TUI exit timeout')),5000);tui.once('close',()=>{clearTimeout(t);r();});});assert.deepEqual(await readFile(join(cwd,'binary.dat')),Buffer.from([0,2]));checks.push('actual Node TTY harness opens /undo-conflict review and Escape preserves selected bytes');}finally{tui.kill();}
